q5__Entrega.java:
public abstract class Entrega {
    //atributos
    private  String codigo;
    double pesoKg;
    Cliente cliente;

    //contrutor

    public Entrega(String codigo, double pesoKg, Cliente cliente) {
        this.codigo = codigo;
        this.pesoKg = pesoKg;
        this.cliente = cliente;
    }

    //get e setters
    public String getCodigo() {
        return codigo;
    }
    public double getPesoKg() {
        return pesoKg;
    }
    public Cliente getCliente() {
        return cliente;
    }

    //metodos
    public abstract double calcularFrete();
    public abstract int getPrazoDias();

    public double calcularTotal(double valorProdutos){
        return valorProdutos + calcularFrete();
    }
    public double calcularTotal(double valorProdutos, double cupom) {

        return calcularTotal(valorProdutos) - cupom;
    }

    public void exibir(){
        System.out.println(this.codigo + " | " + cliente.getNome() + " ("
        + cliente.getCidade() + ") | frete R$ " + calcularFrete()
        + " | prazo " + getPrazoDias() + " dia(s)");
    }

}

q5__EntregaPadrao.java:
public class EntregaPadrao extends Entrega {
    //atributos
    //contrutor

    public EntregaPadrao(String codigo, double pesoKg, Cliente cliente) {
        super(codigo, pesoKg, cliente);
    }

    //get e setters
    //metodos

    @Override
    public double calcularFrete() {
        double frete = 0;
        if (this.pesoKg < 5){
            frete = 12.00;
        } else {
            frete = 12.00 + 3*(pesoKg - 5);
        }
        return frete;
    }

    @Override
    public int getPrazoDias() {
        return 5;
    }
}

q5__EntregaExpressa.java:
public class EntregaExpressa extends EntregaPadrao {
    //atributos
    //contrutor

    public EntregaExpressa(String codigo, double pesoKg, Cliente cliente) {
        super(codigo, pesoKg, cliente);
    }

    //get e setters
    //metodos

    @Override
    public double calcularFrete() {
        return super.calcularFrete() * 2;
    }

    @Override
    public int getPrazoDias() {
        return 1;
    }
}

